#include <stdio.h>
#include <windows.h>
#include <string.h>
#include "process.h"
#include "predict.h"
#include "control.h"
#include "data.h"
typedef struct { DWORD pid; int count; } CandidateRecord;
static CandidateRecord candidates[MAX_PROCESSES];
void show_processes(){ ProcessInfo list[MAX_PROCESSES]; int n,i; n=get_processes(list,MAX_PROCESSES); printf("\n%-8s %-35s %-10s %-12s %-10s\n","PID","PROCESS","CPU %","MEMORY","STATE"); printf("-------------------------------------------------------------------------------\n"); for(i=0;i<n;i++) printf("%-8lu %-35s %-10.2f %-12llu %-10s\n",list[i].pid,list[i].name,list[i].cpu_percent,(unsigned long long)list[i].memory_mb,process_state(list[i].pid)); }
void analyze_process(DWORD pid){ ProcessInfo p; int background_seconds,count; double probability; if(!get_process_info(pid,&p)){ printf("Could not access process.\n"); return; } background_seconds=get_background_seconds(pid); count=get_usage_count(pid)+1; if(p.cpu_percent>=1.0) count++; p.inactive_seconds=background_seconds; p.usage_count=count; probability=predict_usage(count,background_seconds,p.cpu_percent,p.battery,p.memory_mb); p.probability=probability; save_usage(&p); printf("\nPROCESS INFORMATION\n--------------------\n"); printf("PID                 : %lu\n",p.pid); printf("Name                : %s\n",p.name); printf("CPU Usage           : %.2f%%\n",p.cpu_percent); printf("Memory              : %llu MB\n",(unsigned long long)p.memory_mb); printf("Battery             : %d%%\n",p.battery); printf("Background Time     : %d sec\n",background_seconds); printf("Usage Count         : %d\n",count); printf("Future Usage        : %.2f%%\n",probability*100); printf("Decision            : %s\n",decision(probability)); if(is_foreground_process(pid)) printf("Protection          : FOREGROUND PROCESS\n"); else if(!is_safe_to_manage(pid,p.name)) printf("Protection          : SYSTEM/PROTECTED PROCESS\n"); else printf("Protection          : ELIGIBLE USER PROCESS\n"); }
static int find_candidate(DWORD pid){ int i; for(i=0;i<MAX_PROCESSES;i++) if(candidates[i].pid==pid) return i; return -1; }
static int add_candidate(DWORD pid){ int i; for(i=0;i<MAX_PROCESSES;i++) if(candidates[i].pid==0){ candidates[i].pid=pid; candidates[i].count=1; return i; } return -1; }
static void remove_candidate(DWORD pid){ int i; for(i=0;i<MAX_PROCESSES;i++) if(candidates[i].pid==pid){ candidates[i].pid=0; candidates[i].count=0; return; } }
void automatic_engine(){ ProcessInfo list[MAX_PROCESSES]; int n,i,background_seconds,count,candidate_index; double probability; printf("\n========================================\n AUTOMATIC PREDICTIVE ENGINE\n========================================\n"); printf("Monitoring every 10 seconds.\nMinimum background time: 60 seconds.\nThree consecutive candidate checks required.\nForeground processes are always protected.\nSystem processes are protected.\nOnly eligible user processes can be suspended.\nPress Ctrl+C to stop.\n\n"); for(i=0;i<MAX_PROCESSES;i++){ candidates[i].pid=0; candidates[i].count=0; } while(1){ n=get_processes(list,MAX_PROCESSES); printf("\n============================================================\nProcesses detected: %d\n============================================================\n",n); for(i=0;i<n;i++){ if(is_foreground_process(list[i].pid)){ get_background_seconds(list[i].pid); remove_candidate(list[i].pid); continue; } if(is_process_suspended(list[i].pid)) continue; if(!is_safe_to_manage(list[i].pid,list[i].name)) continue; if(get_process_age_seconds(list[i].pid)<30) continue; background_seconds=get_background_seconds(list[i].pid); count=get_usage_count(list[i].pid); if(list[i].cpu_percent>=1.0) count++; list[i].usage_count=count; list[i].inactive_seconds=background_seconds; probability=predict_usage(count,background_seconds,list[i].cpu_percent,list[i].battery,list[i].memory_mb); list[i].probability=probability; save_usage(&list[i]); printf("PID:%-6lu %-25s CPU:%5.2f%% BG:%3ds Prediction:%5.1f%%",list[i].pid,list[i].name,list[i].cpu_percent,background_seconds,probability*100); if(should_suspend(list[i].pid,list[i].name,probability,background_seconds,list[i].cpu_percent)){ candidate_index=find_candidate(list[i].pid); if(candidate_index<0){ candidate_index=add_candidate(list[i].pid); printf(" -> CANDIDATE 1/3"); } else { candidates[candidate_index].count++; if(candidates[candidate_index].count>=3){ if(suspend_process(list[i].pid)){ printf(" -> SUSPENDED"); remove_candidate(list[i].pid); } else printf(" -> SUSPEND FAILED"); } else printf(" -> CANDIDATE %d/3",candidates[candidate_index].count); }} else { remove_candidate(list[i].pid); printf(" -> %s",decision(probability)); } printf("\n"); } resume_foreground_processes(); Sleep(10000); } }
void manual_suspend(){ DWORD pid; ProcessInfo p; printf("Enter PID to suspend: "); scanf("%lu",&pid); if(!get_process_info(pid,&p)){ printf("Could not access process.\n"); return; } if(!is_safe_to_manage(pid,p.name)){ printf("This process is protected from suspension.\n"); return; } if(suspend_process(pid)) printf("Process suspended.\n"); else printf("Could not suspend process.\n"); }
void manual_resume(){ DWORD pid; printf("Enter PID to resume: "); scanf("%lu",&pid); if(resume_process(pid)) printf("Process resumed.\n"); else printf("Could not resume process.\n"); }
int main(){ int choice; DWORD pid; while(1){ printf("\n========================================\n   PREDICTIVE PROCESS FRAMEWORK\n========================================\n1. Show Running Processes\n2. Analyze Process\n3. Suspend Process\n4. Resume Process\n5. Automatic Predictive Engine\n6. Show Usage History\n7. Resume All Managed Processes\n0. Exit\nEnter choice: "); scanf("%d",&choice); switch(choice){ case 1: show_processes(); break; case 2: printf("Enter PID: "); scanf("%lu",&pid); analyze_process(pid); break; case 3: manual_suspend(); break; case 4: manual_resume(); break; case 5: automatic_engine(); break; case 6: show_usage_history(); break; case 7: resume_all_suspended_processes(); break; case 0: resume_all_suspended_processes(); return 0; default: printf("Invalid choice.\n"); } } }
